import{_ as t,o,c as a,a2 as i}from"./chunks/framework.Dkj3JE0_.js";const h=JSON.parse('{"title":"Ethics","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/CFA/C0 Ethics/Ethics.md","filePath":"blogs/CFA/C0 Ethics/Ethics.md"}'),s={name:"blogs/CFA/C0 Ethics/Ethics.md"};function r(n,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ethics" tabindex="-1">Ethics <a class="header-anchor" href="#ethics" aria-label="Permalink to &quot;Ethics&quot;">​</a></h1><h2 id="standard-i-professionalism" tabindex="-1">Standard I Professionalism <a class="header-anchor" href="#standard-i-professionalism" aria-label="Permalink to &quot;Standard I Professionalism&quot;">​</a></h2><h3 id="standard-i-a-knowledge-of-the-law" tabindex="-1">Standard I(A) Knowledge of the Law <a class="header-anchor" href="#standard-i-a-knowledge-of-the-law" aria-label="Permalink to &quot;Standard I(A) Knowledge of the Law&quot;">​</a></h3><blockquote><p>Members and Candidates must understand and comply with all applicable laws, rules, and regulations (including the CFA Institute Code of Ethics and Standards of Professional Conduct) of any government, regulatory organization, licensing agency, or professional association governing their professional activities. In the event of conflict, Members and Candidates must comply with the more strict law, rule, or regulation. Members and Candidates must not knowingly participate or assist in and must dissociate from any violation of such laws, rules, or regulations.</p></blockquote><p>Three duties packed into one Standard: <strong>know</strong>, <strong>comply with the stricter rule</strong>, and <strong>do not knowingly assist — dissociate</strong>.</p><h4 id="what-you-must-know-and-what-you-need-not" tabindex="-1">What you must know (and what you need not) <a class="header-anchor" href="#what-you-must-know-and-what-you-need-not" aria-label="Permalink to &quot;What you must know (and what you need not)&quot;">​</a></h4><ul><li>Understand the laws and regulations that <strong>directly govern</strong> your professional activities and that protect clients.</li><li>You are <strong>not</strong> required to become a compliance expert or to know every law that could conceivably touch your work.</li><li>Stay current when rules change — new products, new channels (social media, apps), and new local/regional/global requirements all count.</li><li>When unsure, use the firm’s compliance channels; seeking counsel is recommended, but <strong>reliance on counsel does not absolve</strong> you if the conduct still violates law or the Code and Standards.</li></ul><h4 id="stricter-of-applicable-law-vs-code-and-standards" tabindex="-1">Stricter of applicable law vs Code and Standards <a class="header-anchor" href="#stricter-of-applicable-law-vs-code-and-standards" aria-label="Permalink to &quot;Stricter of applicable law vs Code and Standards&quot;">​</a></h4><p>“Applicable law” is the law that governs the member’s or candidate’s conduct in the facts of the case. “More strict” means the rule that imposes <strong>greater restrictions</strong> or requires <strong>more protective action</strong> for investors.</p><table tabindex="0"><thead><tr><th>Situation</th><th>Follow</th></tr></thead><tbody><tr><td>Applicable law <strong>stricter</strong> than Code and Standards</td><td>Applicable law</td></tr><tr><td>Applicable law <strong>less strict</strong>, or silent / no securities law</td><td>Code and Standards</td></tr><tr><td>Conduct is legal under local law but violates the Code and Standards</td><td>Code and Standards (do not do it)</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Applicable law is a <strong>floor</strong>, not a ceiling. If local law allows something the Code and Standards forbid (e.g. undisclosed referral fees), you still follow the Code and Standards.</p></div><p>Quick map for multi-jurisdiction cases (NS = no securities law; LS = less strict than Code/Standards; MS = more strict):</p><table tabindex="0"><thead><tr><th>Where you operate / which law applies</th><th>Duty</th></tr></thead><tbody><tr><td>Applicable law is LS or NS</td><td>Adhere to Code and Standards</td></tr><tr><td>Applicable law is MS</td><td>Adhere to that stricter law</td></tr><tr><td>Home law says “law of the locality where business is conducted governs,” and locality is LS/NS</td><td>Code and Standards</td></tr><tr><td>Home law says locality governs, and locality is MS</td><td>That stricter local law</td></tr><tr><td>Choice-of-law points to the <strong>client’s home country</strong></td><td>Whichever is stricter between that country’s law and the Code and Standards — usually: follow the stricter of the two</td></tr></tbody></table><h4 id="knowingly-participate-assist-—-and-dissociation" tabindex="-1">Knowingly participate / assist — and dissociation <a class="header-anchor" href="#knowingly-participate-assist-—-and-dissociation" aria-label="Permalink to &quot;Knowingly participate / assist — and dissociation&quot;">​</a></h4><ul><li>You are responsible for violations you <strong>knowingly</strong> participate in or assist. The Standard also reaches conduct you <strong>know or should know</strong> may contribute to a violation.</li><li>If you have reasonable grounds to believe client or employer activity is illegal or unethical: <strong>dissociate</strong>.</li><li>Escalation path when direct talk fails: <ol><li>Bring it to a supervisor or compliance.</li><li>Step away from the activity (remove your name from reports, refuse the assignment, stop using the misleading material, decline or drop the client).</li><li>In extreme cases, resign.</li></ol></li><li><strong>Inaction while staying associated</strong> can itself be treated as participation or assistance.</li><li>Reporting fellow members/candidates to CFA Institute is <strong>encouraged</strong>; reporting to regulators is required only when <strong>mandatory</strong> under applicable law (otherwise it is discretionary whistleblowing — get legal/compliance advice).</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Using inflated composite performance in solicitations, continuing an underwriting after discovering a misleading prospectus, or staying silent on pay-for-flow disguised as “research” payments are classic assist/dissociate traps — even if you did not create the problem.</p></div><h4 id="cross-border-products-and-distribution" tabindex="-1">Cross-border products and distribution <a class="header-anchor" href="#cross-border-products-and-distribution" aria-label="Permalink to &quot;Cross-border products and distribution&quot;">​</a></h4><p>If you create or maintain products or packages, understand law in both <strong>origination</strong> and <strong>expected sale</strong> jurisdictions. Make reasonable efforts to check that distributors also respect distribution-country rules. When multi-jurisdiction complexity creates doubt, seek compliance or outside counsel.</p><h4 id="recommended-procedures-exam-useful-checklist" tabindex="-1">Recommended procedures (exam-useful checklist) <a class="header-anchor" href="#recommended-procedures-exam-useful-checklist" aria-label="Permalink to &quot;Recommended procedures (exam-useful checklist)&quot;">​</a></h4><p><strong>Individuals</strong></p><ul><li>Stay informed (memos, CLE / continuing education).</li><li>Review written compliance procedures regularly.</li><li>Keep current reference files of key statutes and rules.</li><li>Document dissociation steps; urge the firm to stop the conduct.</li><li>Know distribution-area laws for products you help build or sell.</li></ul><p><strong>Firms (encourage)</strong></p><ul><li>Adopt a code of ethics (e.g. Asset Manager Code as a template).</li><li>Centralize applicable-law information for staff.</li><li>Written protocols for reporting suspected violations.</li></ul><h4 id="exam-traps" tabindex="-1">Exam traps <a class="header-anchor" href="#exam-traps" aria-label="Permalink to &quot;Exam traps&quot;">​</a></h4><ul><li>“Legal counsel said it would be hard to prove” ≠ permission to ignore the violation.</li><li>Home-country charterholder status does <strong>not</strong> override a <strong>stricter</strong> host-country rule (e.g. local ban on personal IPO participation).</li><li>Minimal local insider-trading law does <strong>not</strong> relax Standard II(A) — follow the stricter Code/Standards rule.</li><li>New media (Facebook, X, IM) still need current regulatory compliance; ignorance of new guidance is still a Knowledge-of-the-Law failure.</li></ul><h3 id="standard-i-b-independence-and-objectivity" tabindex="-1">Standard I(B) Independence and Objectivity <a class="header-anchor" href="#standard-i-b-independence-and-objectivity" aria-label="Permalink to &quot;Standard I(B) Independence and Objectivity&quot;">​</a></h3><blockquote><p>Members and Candidates must use reasonable care and judgment to achieve and maintain independence and objectivity in their professional activities. Members and Candidates must not offer, solicit, or accept any gift, benefit, compensation, or consideration that reasonably could be expected to compromise their own or another’s independence and objectivity.</p></blockquote><p>Clients must get work and opinions <strong>unaffected by conflicts or pressure</strong>. Avoid both actual loss of independence/objectivity and situations <strong>perceived</strong> to cause that loss. Recommendations must state your <strong>true</strong> opinion in <strong>clear, unambiguous</strong> language — no soft-pedaling to please bankers, issuers, or sales.</p><h4 id="gifts-benefits-and-influence" tabindex="-1">Gifts, benefits, and influence <a class="header-anchor" href="#gifts-benefits-and-influence" aria-label="Permalink to &quot;Gifts, benefits, and influence&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Source</th><th>Rule of thumb</th></tr></thead><tbody><tr><td><strong>Third parties</strong> seeking influence (issuers, brokers, underwriters, rating sponsors, managers pitching for mandates)</td><td>Modest / token gifts and ordinary business entertainment may be OK; <strong>lavish</strong> gifts, entertainment, IPO allocations for your personal account, or anything that could reasonably compromise judgment → reject. Best practice: reject anything that could threaten independence.</td></tr><tr><td><strong>Clients</strong> (already in a compensation relationship)</td><td>Gifts / “bonuses” are treated as <strong>supplementary compensation</strong>. Disclose to employer <strong>before</strong> acceptance when possible; otherwise disclose promptly after. Disclosure lets the firm monitor favoritism vs other clients.</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Personal oversubscribed IPO allocations</strong> to managers are prohibited under I(B) — quick profits not available to clients.</p></div><p>Offering <strong>or</strong> soliciting compromising gifts violates I(B), including gifts that do not benefit you personally (e.g. donations to a charity or political campaign tied to a hiring decision). Both sides of manager selection / procurement are covered: do not buy influence; do not sell it.</p><h4 id="pressure-points-where-objectivity-breaks" tabindex="-1">Pressure points (where objectivity breaks) <a class="header-anchor" href="#pressure-points-where-objectivity-breaks" aria-label="Permalink to &quot;Pressure points (where objectivity breaks)&quot;">​</a></h4><ul><li><strong>Buy-side clients</strong> pressuring sell-side analysts against downgrades; retaliatory practices (reporting the analyst to the issuer) are improper.</li><li><strong>Investment banking</strong> pressure for favorable research on banking clients/prospects → firewalls, separate reporting lines, no IB veto over research, compensation <strong>not</strong> tied directly to banking deals; disclosures prominent and specific.</li><li><strong>Issuer / corporate access</strong> retaliation fears (cut off from calls/management) do not justify biased ratings.</li><li><strong>Credit rating agencies</strong> — fee and structuring conflicts; users of ratings should be mindful and may need to validate independently.</li><li><strong>Performance measurement</strong> — refuse requests to drop weak accounts from composites or to hide mandate drift.</li><li><strong>Issuer-paid research</strong> — allowed only with true independence, full conflict disclosure, diligence; compensation must be a <strong>flat fee not linked to conclusions</strong> (no success bonus, warrants, or equity kickers).</li><li><strong>Travel funding</strong> — best practice: commercial travel paid by you or your firm. Modest issuer-arranged travel only when commercial options are unavailable (e.g. remote property/mine tour). Sponsored “fact-finding” trips paid by a competing manager you later hire are a perception and conflict hazard.</li></ul><h4 id="recommended-procedures" tabindex="-1">Recommended procedures <a class="header-anchor" href="#recommended-procedures" aria-label="Permalink to &quot;Recommended procedures&quot;">​</a></h4><ul><li>Policy that research on corporate clients reflects the analyst’s <strong>unbiased</strong> opinion; compensation systems that protect research integrity.</li><li><strong>Restricted list</strong> if the firm will not allow adverse opinions — disseminate facts only.</li><li>Pay your own commercial transport and hotels for issuer visits; do not let one issuer always host.</li><li>Token gift limits (per gift and/or annual aggregate, calibrated to local custom); ordinary entertainment OK if not meant to influence.</li><li>Prior approval / disclosure for employee IPO participation; tight limits on private placements; supervise personal trading.</li><li>Written independence policy: research must not report to banking or other compromising departments.</li><li>Senior officer accountable for ethics/compliance; clear internal reporting channels.</li></ul><h4 id="decision-rules-for-vignettes" tabindex="-1">Decision rules for vignettes <a class="header-anchor" href="#decision-rules-for-vignettes" aria-label="Permalink to &quot;Decision rules for vignettes&quot;">​</a></h4><ol><li>Ask: could this gift, fee, trip, or bonus <strong>reasonably</strong> be expected to compromise my judgment — or look that way to a client?</li><li>Third-party inducement vs disclosed client gift — different treatment; disclosure is mandatory for client gifts.</li><li>Flat fee for issuer-paid work → possible; fee tied to “attracting investors” or positive tone → violation.</li><li>Intrafirm pressure (sales inventory, banking deal, boss’s prior “buy”) → still issue <strong>your</strong> independent conclusion, or refuse the constrained assignment; consider a restricted list.</li><li>Hiring / “pay-to-play” — political contributions or lavish entertainment aimed at winning mandates compromise the other party’s objectivity and violate I(B) for the offeror.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Perception matters. Even when a modest business-only site visit paid by the issuer may not violate I(B), firm policies that always self-pay are safer. For manager due-diligence trips, your employer or the plan should pay base travel/lodging.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Service-fee / trailer arrangements that lock you into pushing one product family after disclosure failures (or after underperformance, because you need the fee) are independence failures — often paired with VI(A) conflict disclosure issues.</p></div>',40)])])}const g=t(s,[["render",r]]);export{h as __pageData,g as default};
